def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    traffic_light_patches = image_patch.find("traffic light")
    if not traffic_light_patches: 
        return image_patch

    traffic_light = traffic_light_patches[0]

    people = image_patch.find("person")
    if not people: 
        return image_patch

    people_nearby = [p for p in people if abs(p.horizontal_center - traffic_light.horizontal_center) < 50]

    if not people_nearby: 
        return image_patch

    return people_nearby[0]

